import { Equation } from '../equations/Equation'
import { Vec3 } from '../math/Vec3'
import type { Body } from '../objects/Body'

/**
 * Rotational motor constraint. Tries to keep the relative angular velocity of the bodies to a given value.
 */
export class RotationalMotorEquation extends Equation {
 /**
 * World oriented rotational axis.
 */
 axisA: Vec3
 /**
 * World oriented rotational axis.
 */
 axisB: Vec3
 /**
 * Motor velocity.
 */
 targetVelocity: number

 constructor(bodyA: Body, bodyB: Body, maxForce = 1e6) {
 super(bodyA, bodyB, -maxForce, maxForce)

 this.axisA = new Vec3()
 this.axisB = new Vec3()
 this.targetVelocity = 0
 }

 computeB(h: number): number {
 const a = this.a
 const b = this.b
 const bi = this.bi
 const bj = this.bj
 const axisA = this.axisA
 const axisB = this.axisB
 const GA = this.jacobianElementA
 const GB = this.jacobianElementB

 // g = 0
 // gdot = axisA * wi - axisB * wj
 // gdot = G * W = G * [vi wi vj wj]
 // =>
 // G = [0 axisA 0 -axisB]

 GA.rotational.copy(axisA)
 axisB.negate(GB.rotational)

 const GW = this.computeGW() - this.targetVelocity
 const GiMf = this.computeGiMf()

 const B = -GW * b - h * GiMf

 return B
 }
}

import { Solver } from '../solver/Solver'
import type { World } from '../world/World'

/**
 * Constraint equation Gauss-Seidel solver.
 * @todo The spook parameters should be specified for each constraint, not globally.
 * @see https://www8.cs.umu.se/kurser/5DV058/VT09/lectures/spooknotes.pdf
 */
export class GSSolver extends Solver {
 /**
 * The number of solver iterations determines quality of the constraints in the world.
 * The more iterations, the more correct simulation. More iterations need more computations though. If you have a large gravity force in your world, you will need more iterations.
 */
 iterations: number

 /**
 * When tolerance is reached, the system is assumed to be converged.
 */
 tolerance: number

 /**
 * @todo remove useless constructor
 */
 constructor() {
 super()

 this.iterations = 10
 this.tolerance = 1e-7
 }

 /**
 * Solve
 * @return number of iterations performed
 */
 solve(dt: number, world: World): number {
 let iter = 0
 const maxIter = this.iterations
 const tolSquared = this.tolerance * this.tolerance
 const equations = this.equations
 const Neq = equations.length
 const bodies = world.bodies
 const Nbodies = bodies.length
 const h = dt
 let q
 let B
 let invC
 let deltalambda
 let deltalambdaTot
 let GWlambda
 let lambdaj

 // Update solve mass
 if (Neq !== 0) {
 for (let i = 0; i !== Nbodies; i++) {
 bodies[i].updateSolveMassProperties()
 }
 }

 // Things that do not change during iteration can be computed once
 const invCs = GSSolver_solve_invCs

 const Bs = GSSolver_solve_Bs
 const lambda = GSSolver_solve_lambda
 invCs.length = Neq
 Bs.length = Neq
 lambda.length = Neq
 for (let i = 0; i !== Neq; i++) {
 const c = equations[i] as any
 lambda[i] = 0.0
 Bs[i] = c.computeB(h)
 invCs[i] = 1.0 / c.computeC()
 }

 if (Neq !== 0) {
 // Reset vlambda
 for (let i = 0; i !== Nbodies; i++) {
 const b = bodies[i]
 const vlambda = b.vlambda
 const wlambda = b.wlambda
 vlambda.set(0, 0, 0)
 wlambda.set(0, 0, 0)
 }

 // Iterate over equations
 for (iter = 0; iter !== maxIter; iter++) {
 // Accumulate the total error for each iteration.
 deltalambdaTot = 0.0

 for (let j = 0; j !== Neq; j++) {
 const c = equations[j]

 // Compute iteration
 B = Bs[j]
 invC = invCs[j]
 lambdaj = lambda[j]
 GWlambda = c.computeGWlambda()
 deltalambda = invC * (B - GWlambda - c.eps * lambdaj)

 // Clamp if we are not within the min/max interval
 if (lambdaj + deltalambda < c.minForce) {
 deltalambda = c.minForce - lambdaj
 } else if (lambdaj + deltalambda > c.maxForce) {
 deltalambda = c.maxForce - lambdaj
 }
 lambda[j] += deltalambda

 deltalambdaTot += deltalambda > 0.0 ? deltalambda : -deltalambda // abs(deltalambda)

 c.addToWlambda(deltalambda)
 }

 // If the total error is small enough - stop iterate
 if (deltalambdaTot * deltalambdaTot < tolSquared) {
 break
 }
 }

 // Add result to velocity
 for (let i = 0; i !== Nbodies; i++) {
 const b = bodies[i]
 const v = b.velocity
 const w = b.angularVelocity

 b.vlambda.vmul(b.linearFactor, b.vlambda)
 v.vadd(b.vlambda, v)

 b.wlambda.vmul(b.angularFactor, b.wlambda)
 w.vadd(b.wlambda, w)
 }

 // Set the `.multiplier` property of each equation
 let l = equations.length
 const invDt = 1 / h
 while (l--) {
 equations[l].multiplier = lambda[l] * invDt
 }
 }

 return iter
 }
}

// Just temporary number holders that we want to reuse each iteration.
const GSSolver_solve_lambda: number[] = []
const GSSolver_solve_invCs: number[] = []
const GSSolver_solve_Bs: number[] = []

import { PointToPointConstraint } from '../constraints/PointToPointConstraint'
import { RotationalEquation } from '../equations/RotationalEquation'
import { RotationalMotorEquation } from '../equations/RotationalMotorEquation'
import { Vec3 } from '../math/Vec3'
import type { Body } from '../objects/Body'

export type HingeConstraintOptions = ConstructorParameters [2]

/**
 * Hinge constraint. Think of it as a door hinge. It tries to keep the door in the correct place and with the correct orientation.
 */
export class HingeConstraint extends PointToPointConstraint {
 /**
 * Rotation axis, defined locally in bodyA.
 */
 axisA: Vec3
 /**
 * Rotation axis, defined locally in bodyB.
 */
 axisB: Vec3

 rotationalEquation1: RotationalEquation
 rotationalEquation2: RotationalEquation
 motorEquation: RotationalMotorEquation

 constructor(
 bodyA: Body,
 bodyB: Body,
 options: {
 /**
 * A point defined locally in bodyA. This defines the offset of axisA.
 */
 pivotA?: Vec3
 /**
 * A point defined locally in bodyB. This defines the offset of axisB.
 */
 pivotB?: Vec3
 /**
 * An axis that bodyA can rotate around, defined locally in bodyA.
 */
 axisA?: Vec3
 /**
 * An axis that bodyB can rotate around, defined locally in bodyB.
 */
 axisB?: Vec3
 /**
 * Wheter to collide the connected bodies or not.
 * @default false
 */
 collideConnected?: boolean
 /**
 * The maximum force that should be applied to constrain the bodies.
 * @default 1e6
 */
 maxForce?: number
 } = {}
 ) {
 const maxForce = typeof options.maxForce !== 'undefined' ? options.maxForce : 1e6
 const pivotA = options.pivotA ? options.pivotA.clone() : new Vec3()
 const pivotB = options.pivotB ? options.pivotB.clone() : new Vec3()

 super(bodyA, pivotA, bodyB, pivotB, maxForce)

 const axisA = (this.axisA = options.axisA ? options.axisA.clone() : new Vec3(1, 0, 0))
 axisA.normalize()

 const axisB = (this.axisB = options.axisB ? options.axisB.clone() : new Vec3(1, 0, 0))
 axisB.normalize()

 this.collideConnected = !!options.collideConnected

 const rotational1 = (this.rotationalEquation1 = new RotationalEquation(bodyA, bodyB, options))
 const rotational2 = (this.rotationalEquation2 = new RotationalEquation(bodyA, bodyB, options))
 const motor = (this.motorEquation = new RotationalMotorEquation(bodyA, bodyB, maxForce))
 motor.enabled = false // Not enabled by default

 // Equations to be fed to the solver
 this.equations.push(rotational1, rotational2, motor)
 }

 /**
 * enableMotor
 */
 enableMotor(): void {
 this.motorEquation.enabled = true
 }

 /**
 * disableMotor
 */
 disableMotor(): void {
 this.motorEquation.enabled = false
 }

 /**
 * setMotorSpeed
 */
 setMotorSpeed(speed: number): void {
 this.motorEquation.targetVelocity = speed
 }

 /**
 * setMotorMaxForce
 */
 setMotorMaxForce(maxForce: number): void {
 this.motorEquation.maxForce = maxForce
 this.motorEquation.minForce = -maxForce
 }

 /**
 * update
 */
 update(): void {
 const bodyA = this.bodyA
 const bodyB = this.bodyB
 const motor = this.motorEquation
 const r1 = this.rotationalEquation1
 const r2 = this.rotationalEquation2
 const worldAxisA = HingeConstraint_update_tmpVec1
 const worldAxisB = HingeConstraint_update_tmpVec2

 const axisA = this.axisA
 const axisB = this.axisB

 super.update()

 // Get world axes
 bodyA.quaternion.vmult(axisA, worldAxisA)
 bodyB.quaternion.vmult(axisB, worldAxisB)

 worldAxisA.tangents(r1.axisA, r2.axisA)
 r1.axisB.copy(worldAxisB)
 r2.axisB.copy(worldAxisB)

 if (this.motorEquation.enabled) {
 bodyA.quaternion.vmult(this.axisA, motor.axisA)
 bodyB.quaternion.vmult(this.axisB, motor.axisB)
 }
 }
}

const HingeConstraint_update_tmpVec1 = new Vec3()
const HingeConstraint_update_tmpVec2 = new Vec3()

import { Utils } from '../utils/Utils'
import type { Body } from '../objects/Body'
import type { Equation } from '../equations/Equation'

export type ConstraintOptions = ConstructorParameters [2]

/**
 * Constraint base class
 */
export class Constraint {
 /**
 * Equations to be solved in this constraint.
 */
 equations: Equation[]
 /**
 * Body A.
 */
 bodyA: Body
 /**
 * Body B.
 */
 bodyB: Body
 id: number
 /**
 * Set to false if you don't want the bodies to collide when they are connected.
 */
 collideConnected: boolean

 static idCounter = 0

 constructor(
 bodyA: Body,
 bodyB: Body,
 options: {
 /**
 * Set to false if you don't want the bodies to collide when they are connected.
 * @default true
 */
 collideConnected?: boolean
 /**
 * Set to false if you don't want the bodies to wake up when they are connected.
 * @default true
 */
 wakeUpBodies?: boolean
 } = {}
 ) {
 options = Utils.defaults(options, {
 collideConnected: true,
 wakeUpBodies: true,
 })

 this.equations = []
 this.bodyA = bodyA
 this.bodyB = bodyB
 this.id = Constraint.idCounter++
 this.collideConnected = options.collideConnected!

 if (options.wakeUpBodies) {
 if (bodyA) {
 bodyA.wakeUp()
 }
 if (bodyB) {
 bodyB.wakeUp()
 }
 }
 }

 /**
 * Update all the equations with data.
 */
 update(): void {
 throw new Error('method update() not implmemented in this Constraint subclass!')
 }

 /**
 * Enables all equations in the constraint.
 */
 enable(): void {
 const eqs = this.equations
 for (let i = 0; i < eqs.length; i++) {
 eqs[i].enabled = true
 }
 }

 /**
 * Disables all equations in the constraint.
 */
 disable(): void {
 const eqs = this.equations
 for (let i = 0; i < eqs.length; i++) {
 eqs[i].enabled = false
 }
 }
}

import { ConvexPolyhedron } from '../shapes/ConvexPolyhedron'
import { Vec3 } from '../math/Vec3'
import { Shape } from './Shape'

/**
 * Cylinder class.
 * @example
 * const radiusTop = 0.5
 * const radiusBottom = 0.5
 * const height = 2
 * const numSegments = 12
 * const cylinderShape = new CANNON.Cylinder(radiusTop, radiusBottom, height, numSegments)
 * const cylinderBody = new CANNON.Body({ mass: 1, shape: cylinderShape })
 * world.addBody(cylinderBody)
 */
export class Cylinder extends ConvexPolyhedron {
 /** The radius of the top of the Cylinder. */
 radiusTop: number
 /** The radius of the bottom of the Cylinder. */
 radiusBottom: number
 /** The height of the Cylinder. */
 height: number
 /** The number of segments to build the cylinder out of. */
 numSegments: number

 /**
 * @param radiusTop The radius of the top of the Cylinder.
 * @param radiusBottom The radius of the bottom of the Cylinder.
 * @param height The height of the Cylinder.
 * @param numSegments The number of segments to build the cylinder out of.
 */
 constructor(radiusTop: number = 1, radiusBottom: number = 1, height: number = 1, numSegments: number = 8) {
 if (radiusTop < 0) {
 throw new Error('The cylinder radiusTop cannot be negative.')
 }

 if (radiusBottom < 0) {
 throw new Error('The cylinder radiusBottom cannot be negative.')
 }

 const N = numSegments
 const vertices = []
 const axes = []
 const faces = []
 const bottomface = []
 const topface = []
 const cos = Math.cos
 const sin = Math.sin

 // First bottom point
 vertices.push(new Vec3(-radiusBottom * sin(0), -height * 0.5, radiusBottom * cos(0)))
 bottomface.push(0)

 // First top point
 vertices.push(new Vec3(-radiusTop * sin(0), height * 0.5, radiusTop * cos(0)))
 topface.push(1)

 for (let i = 0; i < N; i++) {
 const theta = ((2 * Math.PI) / N) * (i + 1)
 const thetaN = ((2 * Math.PI) / N) * (i + 0.5)
 if (i < N - 1) {
 // Bottom
 vertices.push(new Vec3(-radiusBottom * sin(theta), -height * 0.5, radiusBottom * cos(theta)))
 bottomface.push(2 * i + 2)
 // Top
 vertices.push(new Vec3(-radiusTop * sin(theta), height * 0.5, radiusTop * cos(theta)))
 topface.push(2 * i + 3)

 // Face
 faces.push([2 * i, 2 * i + 1, 2 * i + 3, 2 * i + 2])
 } else {
 faces.push([2 * i, 2 * i + 1, 1, 0]) // Connect
 }

 // Axis: we can cut off half of them if we have even number of segments
 if (N % 2 === 1 || i < N / 2) {
 axes.push(new Vec3(-sin(thetaN), 0, cos(thetaN)))
 }
 }
 faces.push(bottomface)
 axes.push(new Vec3(0, 1, 0))

 // Reorder top face
 const temp = []
 for (let i = 0; i < topface.length; i++) {
 temp.push(topface[topface.length - i - 1])
 }
 faces.push(temp)

 super({ vertices, faces, axes })

 this.type = Shape.types.CYLINDER
 this.radiusTop = radiusTop
 this.radiusBottom = radiusBottom
 this.height = height
 this.numSegments = numSegments
 }
}

import { PointToPointConstraint } from '../constraints/PointToPointConstraint'
import { RotationalEquation } from '../equations/RotationalEquation'
import { Vec3 } from '../math/Vec3'
import type { Body } from '../objects/Body'
import type { RotationalMotorEquation } from '../equations/RotationalMotorEquation'

export type LockConstraintOptions = ConstructorParameters [2]

/**
 * Lock constraint. Will remove all degrees of freedom between the bodies.
 */
export class LockConstraint extends PointToPointConstraint {
 xA: Vec3
 xB: Vec3
 yA: Vec3
 yB: Vec3
 zA: Vec3
 zB: Vec3

 rotationalEquation1: RotationalEquation
 rotationalEquation2: RotationalEquation
 rotationalEquation3: RotationalEquation
 motorEquation?: RotationalMotorEquation

 constructor(
 bodyA: Body,
 bodyB: Body,
 options: {
 /**
 * The maximum force that should be applied to constrain the bodies.
 * @default 1e6
 */
 maxForce?: number
 } = {}
 ) {
 const maxForce = typeof options.maxForce !== 'undefined' ? options.maxForce : 1e6

 // Set pivot point in between
 const pivotA = new Vec3()
 const pivotB = new Vec3()
 const halfWay = new Vec3()
 bodyA.position.vadd(bodyB.position, halfWay)
 halfWay.scale(0.5, halfWay)
 bodyB.pointToLocalFrame(halfWay, pivotB)
 bodyA.pointToLocalFrame(halfWay, pivotA)

 // The point-to-point constraint will keep a point shared between the bodies
 super(bodyA, pivotA, bodyB, pivotB, maxForce)

 // Store initial rotation of the bodies as unit vectors in the local body spaces
 this.xA = bodyA.vectorToLocalFrame(Vec3.UNIT_X)
 this.xB = bodyB.vectorToLocalFrame(Vec3.UNIT_X)
 this.yA = bodyA.vectorToLocalFrame(Vec3.UNIT_Y)
 this.yB = bodyB.vectorToLocalFrame(Vec3.UNIT_Y)
 this.zA = bodyA.vectorToLocalFrame(Vec3.UNIT_Z)
 this.zB = bodyB.vectorToLocalFrame(Vec3.UNIT_Z)

 // ...and the following rotational equations will keep all rotational DOF's in place
 const r1 = (this.rotationalEquation1 = new RotationalEquation(bodyA, bodyB, options))
 const r2 = (this.rotationalEquation2 = new RotationalEquation(bodyA, bodyB, options))
 const r3 = (this.rotationalEquation3 = new RotationalEquation(bodyA, bodyB, options))

 this.equations.push(r1, r2, r3)
 }

 /**
 * update
 */
 update(): void {
 const bodyA = this.bodyA
 const bodyB = this.bodyB
 const motor = this.motorEquation
 const r1 = this.rotationalEquation1
 const r2 = this.rotationalEquation2
 const r3 = this.rotationalEquation3
 const worldAxisA = LockConstraint_update_tmpVec1
 const worldAxisB = LockConstraint_update_tmpVec2

 super.update()

 // These vector pairs must be orthogonal
 bodyA.vectorToWorldFrame(this.xA, r1.axisA)
 bodyB.vectorToWorldFrame(this.yB, r1.axisB)

 bodyA.vectorToWorldFrame(this.yA, r2.axisA)
 bodyB.vectorToWorldFrame(this.zB, r2.axisB)

 bodyA.vectorToWorldFrame(this.zA, r3.axisA)
 bodyB.vectorToWorldFrame(this.xB, r3.axisB)
 }
}

const LockConstraint_update_tmpVec1 = new Vec3()
const LockConstraint_update_tmpVec2 = new Vec3()

